<?php
$page='expenses';$title='Expenses';require_once __DIR__.'/includes/functions.php';require_login();$uid=$_SESSION['user_id'];verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'';$id=(int)($_POST['id']??0);$desc=trim($_POST['description']??'');$cat=trim($_POST['category']??'');$amount=(float)($_POST['amount']??0);$date=$_POST['transaction_date']??date('Y-m-d');$notes=trim($_POST['notes']??'');if($action==='delete'){$q=$pdo->prepare("DELETE FROM transactions WHERE id=? AND user_id=? AND type='expense'");$q->execute([$id,$uid]);set_flash('Expense deleted.');}elseif($desc!==''&&$cat!==''&&$amount>0){if($action==='update'){$q=$pdo->prepare("UPDATE transactions SET description=?,category=?,amount=?,transaction_date=?,notes=? WHERE id=? AND user_id=? AND type='expense'");$q->execute([$desc,$cat,$amount,$date,$notes,$id,$uid]);set_flash('Expense updated.');}else{$q=$pdo->prepare("INSERT INTO transactions(user_id,type,description,category,amount,transaction_date,notes) VALUES(?,'expense',?,?,?,?,?)");$q->execute([$uid,$desc,$cat,$amount,$date,$notes]);set_flash('Expense added.');$b=$pdo->prepare("SELECT amount FROM budgets WHERE user_id=? AND period='monthly' ORDER BY start_date DESC LIMIT 1");$b->execute([$uid]);$budget=(float)($b->fetchColumn()?:0);$tot=get_totals($pdo,$uid,date('Y-m-01'),date('Y-m-t'));if($budget>0&&$tot['expense']>$budget)add_notification($pdo,$uid,'Your expenses have exceeded your monthly budget.');}}else set_flash('Enter a description, category, and valid amount.','error');header('Location: expenses.php');exit;}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare("SELECT * FROM transactions WHERE id=? AND user_id=? AND type='expense'");$q->execute([(int)$_GET['edit'],$uid]);$edit=$q->fetch();}
$search=trim($_GET['q']??'');$category=$_GET['category']??'';$sql="SELECT * FROM transactions WHERE user_id=? AND type='expense'";$args=[$uid];if($search!==''){$sql.=' AND (description LIKE ? OR category LIKE ?)';$args[]="%$search%";$args[]="%$search%";}if($category!==''){$sql.=' AND category=?';$args[]=$category;}$sql.=' ORDER BY transaction_date DESC,id DESC';$q=$pdo->prepare($sql);$q->execute($args);$rows=$q->fetchAll();$categories=['Food','Transportation','School','Personal Needs','Entertainment','Others'];require 'includes/header.php';?>
<div class="page-head"><div><h1>Expense Management</h1><p>Add, edit, delete, and view expense history.</p></div><a class="btn" href="expenses.php?action=add">＋ Add Expense</a></div>
<?php if(isset($_GET['action'])||$edit):?><div class="card form-card"><h3><?= $edit?'Edit Expense':'Add Expense' ?></h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="<?=$edit?'update':'add'?>"><?php if($edit):?><input type="hidden" name="id" value="<?=$edit['id']?>"><?php endif;?><div class="field"><label>Description</label><input name="description" required value="<?=e($edit['description']??'')?>"></div><div class="field"><label>Category</label><select name="category" required><?php foreach($categories as $c):?><option <?=($edit['category']??'')===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select></div><div class="field"><label>Amount (₱)</label><input type="number" name="amount" min="0.01" step="0.01" required value="<?=e($edit['amount']??'')?>"></div><div class="field"><label>Date</label><input type="date" name="transaction_date" required value="<?=e($edit['transaction_date']??date('Y-m-d'))?>"></div><div class="field"><label>Notes (optional)</label><textarea name="notes"><?=e($edit['notes']??'')?></textarea></div><button class="btn">Save Expense</button> <a class="btn secondary" href="expenses.php">Cancel</a></form></div><?php endif;?>
<form class="toolbar" method="get"><input name="q" placeholder="Search expenses..." value="<?=e($search)?>"><select name="category"><option value="">All Categories</option><?php foreach($categories as $c):?><option <?= $category===$c?'selected':'' ?>><?=e($c)?></option><?php endforeach;?></select><button class="btn">Search</button></form><div class="card table-wrap"><table><thead><tr><th>Date</th><th>Description</th><th>Category</th><th>Amount</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['transaction_date'])?></td><td><?=e($r['description'])?></td><td><?=e($r['category'])?></td><td><?=money($r['amount'])?></td><td><div class="actions"><a class="btn" href="expenses.php?edit=<?=$r['id']?>">Edit</a><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger" data-confirm="Delete this expense?">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><p class="empty">No expenses found.</p><?php endif;?></div><?php require 'includes/footer.php';?>
